const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Approximate bounding box for Southern Ethiopia
    const southEthiopia = ee.Geometry.BBox(34.0, 3.0, 48.0, 8.0); // minLon, minLat, maxLon, maxLat

    // Date range for current period (Oct-Nov 2021)
    const start2021 = '2021-10-01';
    const end2021 = '2021-11-30';

    // Date range for long-term average period (Oct-Nov for 2000-2013)
    const startLTA = '2000-10-01';
    const endLTA = '2013-11-30';
    const numYearsLTA = 14; // From 2000 to 2013 inclusive

    const collectionId = 'UCSB-CHG/CHIRPS/DAILY';
    const precipitationBand = 'precipitation';
    const scale = 5000; // Use a reasonable scale to avoid memory issues

    // 2. Data Acquisition & Check for Current Period (2021)
    let chirps2021 = ee.ImageCollection(collectionId)
      .filterBounds(southEthiopia)
      .filterDate(start2021, end2021);

    const size2021 = await chirps2021.size().getInfo();
    if (size2021 === 0) {
      console.log(`2021 Images: 0`);
      console.log("C1: Empty Collection (No CHIRPS data for Oct-Nov 2021).");
      return;
    }
    console.log(`2021 Images: ${size2021}`);

    // Sum precipitation for the 2021 period
    const totalPrecip2021 = chirps2021.select(precipitationBand).sum();

    // 3. Data Acquisition & Check for Long-Term Average Period (2000-2013)
    let chirpsLTA = ee.ImageCollection(collectionId)
      .filterBounds(southEthiopia)
      .filterDate(startLTA, endLTA);

    const sizeLTA = await chirpsLTA.size().getInfo();
    if (sizeLTA === 0) {
      console.log(`LTA Images: 0`);
      console.log("C1: Empty Collection (No CHIRPS data for Oct-Nov 2000-2013).");
      return;
    }
    console.log(`LTA Images: ${sizeLTA}`);

    // Sum precipitation for the entire LTA period (2000-2013 Oct-Nov)
    const totalPrecipLTA = chirpsLTA.select(precipitationBand).sum();

    // Calculate the average Oct-Nov precipitation for the LTA period
    // This is the total sum divided by the number of years (14)
    const avgPrecipLTA = totalPrecipLTA.divide(numYearsLTA);

    // 4. Calculation of Regional Mean Precipitation
    const reducer = ee.Reducer.mean();

    const getRegionMean = async (image, geometry) => {
      const result = await image.reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9,
        tileScale: 16 // Increase tileScale for large regions
      }).get(precipitationBand).getInfo();
      return result;
    };

    const meanPrecip2021 = await getRegionMean(totalPrecip2021, southEthiopia);
    const meanAvgPrecipLTA = await getRegionMean(avgPrecipLTA, southEthiopia);

    // 5. Validation & Final Answer
    if (meanPrecip2021 === null || isNaN(meanPrecip2021) ||
        meanAvgPrecipLTA === null || isNaN(meanAvgPrecipLTA)) {
      console.log(`2021 Avg Precip: ${meanPrecip2021}, LTA Avg Precip: ${meanAvgPrecipLTA}`);
      console.log("C3: Calculation Failure (Result is None or NaN).");
      return;
    }

    console.log(`2021 Oct-Nov Total Avg Rainfall: ${meanPrecip2021.toFixed(2)} mm`);
    console.log(`LTA (2000-2013) Oct-Nov Avg Rainfall: ${meanAvgPrecipLTA.toFixed(2)} mm`);

    if (meanPrecip2021 < meanAvgPrecipLTA) {
      console.log("A"); // Yes, 2021 received less rainfall
    } else {
      console.log("B"); // No, 2021 received equal or more rainfall
    }

  } catch (e) {
    console.error("D: An error occurred during processing.", e);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
